package net.civeira.phylax.features.access.userprofile.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.userprofile.domain.UserProfile;
import net.civeira.phylax.features.access.userprofile.domain.gateway.UserProfileCursor;
import net.civeira.phylax.features.access.userprofile.domain.gateway.UserProfileFilter;

class UserProfileSlider extends Slider<UserProfile> {

  /**
   * @autogenerated SlideGenerator
   */
  private final UserProfileCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final UserProfileFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<UserProfileFilter, UserProfileCursor, Iterator<UserProfile>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  UserProfileSlider(final Iterator<UserProfile> multi, final int limit,
      final BiFunction<UserProfileFilter, UserProfileCursor, Iterator<UserProfile>> gateway,
      final UserProfileFilter filter, final UserProfileCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param userProfiles
   * @param limit
   * @return
   */
  @Override
  public Iterator<UserProfile> next(List<UserProfile> userProfiles, int limit) {
    UserProfile last = userProfiles.get(userProfiles.size() - 1);
    UserProfileCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
